    "cc.settings.deliveryTitle": "Yetkazish usuli",
    "cc.settings.deliverySub": "Tayyor post Telegramga qanday chiqadi",
    "cc.delivery.approval.infoFull": "<b>Tavsiya etiladi.</b> AI topgan post mobil ilovada <b>Navbat</b> tabida ko'rinadi. Siz matnni tahrirlash, qisqartirish yoki rad etish imkoniga egasiz. Tasdiqlagan post belgilangan vaqtda kanalga yuboriladi.",
    "cc.delivery.twoStage.infoFull": "<b>2 bosqichli oqim.</b> AI arzon model bilan post topadi va <b>Muxbir AI bot</b> orqali kompaniyangizning Telegram chatlariga taklif yuboradi (rasm + sarlavha + qisqacha). «Muxbirda yozish» tugmasini bossangiz — kuchli <b>gemini-3.1-pro</b> to'liq yozadi va yana tasdiq so'raydi. Kanalga chiqarsangiz oylik limitdan 1 kamayadi; chiqarmasangiz 50 kredit yechiladi. Xuddi shu amallar <b>Navbat</b> tabida ham bor.<br><b>Eslatma:</b> avval <b>Telegram chatlar</b> bo'limida chat ID qo'shing.",
    "cc.delivery.direct.warnFull": "<b>Diqqat:</b> postlar mobil ilovada ko'rinmaydi va tasdiqsiz kanalga chiqadi. AI xatosi yoki noto'g'ri matn bo'lsa ham to'g'ridan-to'g'ri abonentlarga boradi. Faqat ishonchli prompt bo'lganda yoqing.",
