    "cc.settings.bufferUnit": "ta post doim tayyor turadi",
    "cc.settings.bufferInfo": "<b>Buffer nima?</b> Bot oldindan <b>{n} ta</b> post yig'ib qo'yadi va mobil ilovaga yuboradi. Siz ularni ko'rib chiqasiz. Har intervalda bitta tasdiqlangan post kanalga ketadi.<br><br><b>Misol:</b> buffer = 5, interval = 3 soat → ilovada 5 ta post navbatda turadi → har 3 soatda 1 tasi Telegramga chiqadi. Buferni oshirsa — keyin tasdiqlash uchun ko'proq vaqtingiz bo'ladi.",
