    "cc.settings.deliverySub": "Как готовый пост выходит в Telegram",
    "cc.delivery.approval.infoFull": "<b>Рекомендуется.</b> Найденный AI пост появляется на вкладке <b>Очередь</b> в мобильном приложении. Вы можете редактировать, сократить или отклонить текст. Подтверждённый пост отправляется в канал в назначенное время.",
    "cc.delivery.twoStage.infoFull": "<b>Двухэтапный поток.</b> AI находит пост дешёвой моделью и через <b>бота Muxbir AI</b> отправляет предложение в Telegram-чаты вашей компании (фото + заголовок + краткое описание). Нажав «Написать в Muxbir» — мощная <b>gemini-3.1-pro</b> напишет полностью и снова запросит подтверждение. При публикации в канал из месячного лимита списывается 1; если не публикуете — списывается 50 кредитов. Те же действия доступны на вкладке <b>Очередь</b>.<br><b>Примечание:</b> сначала добавьте chat ID в разделе <b>Telegram-чаты</b>.",
    "cc.delivery.direct.warnFull": "<b>Внимание:</b> посты не отображаются в мобильном приложении и выходят в канал без подтверждения. Даже при ошибке AI или неверном тексте они напрямую попадают к подписчикам. Включайте только при надёжном промпте.",
