    "cc.settings.bufferLabel": "Посты в очереди (буфер)",
    "cc.settings.bufferUnit": "постов всегда наготове",
    "cc.settings.bufferInfo": "<b>Что такое буфер?</b> Бот заранее собирает <b>{n}</b> постов и отправляет их в мобильное приложение. Вы их просматриваете. На каждом интервале в канал уходит один подтверждённый пост.<br><br><b>Пример:</b> буфер = 5, интервал = 3 часа → в приложении 5 постов в очереди → каждые 3 часа 1 из них выходит в Telegram. Увеличив буфер, вы получите больше времени на подтверждение.",
