    "cc.settings.deliveryTitle": "Delivery method",
    "cc.settings.deliverySub": "How the finished post is published to Telegram",
    "cc.delivery.approval.infoFull": "<b>Recommended.</b> The post the AI finds appears on the <b>Queue</b> tab in the mobile app. You can edit, shorten, or reject the text. The approved post is sent to the channel at the scheduled time.",
    "cc.delivery.twoStage.infoFull": "<b>Two-stage flow.</b> The AI finds a post with a cheaper model and, via the <b>Muxbir AI bot</b>, sends a suggestion to your company's Telegram chats (image + title + summary). When you tap \"Write in Muxbir\" — the powerful <b>gemini-3.1-pro</b> writes the full text and asks for approval again. Publishing to the channel uses 1 of your monthly limit; if you don't publish, 50 credits are charged. The same actions are also available on the <b>Queue</b> tab.<br><b>Note:</b> first add a chat ID in the <b>Telegram chats</b> section.",
    "cc.delivery.direct.warnFull": "<b>Note:</b> posts do not appear in the mobile app and are published to the channel without approval. Even an AI error or incorrect text goes straight to subscribers. Enable only with a reliable prompt.",
    "cc.settings.scheduleTitle": "Scheduling",
    "cc.settings.scheduleSub": "When and how many posts are published",
    "cc.settings.intervalCardSub": "Once every N hours",
    "cc.settings.scheduledCardSub": "A batch at specific hours of the day",
    "cc.settings.intervalPreview": "Every <b>{every}</b> one post is sent to Telegram.",
    "cc.settings.intervalPreviewApproval": "The first post approved by the user is sent.",
    "cc.settings.intervalPreviewAuto": "The post is published automatically without approval.",
    "cc.settings.bufferLabel": "Queued posts (buffer)",
    "cc.settings.bufferUnit": "posts kept ready at all times",
    "cc.settings.bufferInfo": "<b>What is the buffer?</b> The bot collects <b>{n}</b> posts in advance and sends them to the mobile app. You review them. On each interval, one approved post goes to the channel.<br><br><b>Example:</b> buffer = 5, interval = 3 hours → 5 posts queue in the app → every 3 hours 1 of them is published to Telegram. Increasing the buffer gives you more time to approve.",
    "cc.settings.collectBeforeLabel": "How many minutes ahead the post suggestion arrives",
    "cc.settings.minutesBefore": "minutes before",
    "cc.settings.collectBeforeHint": "For example: interval 60 minutes, this value 10 — the suggestion reaches the Telegram bot at minute 50. 0 = always collect.",
    "cc.settings.twoStageBufferLabel": "How many variants per proposal",
    "cc.settings.twoStageBufferUnit": "variant(s)",
    "cc.settings.twoStageBufferHint": "Each proposal will prepare this many flash-written variants (1-3). You'll see each one separately in the bot and on the site — write one, drop another, leave one queued, or cancel all of them.",
    "cc.settings.noTimes": "No time added yet. Select a time below.",
    "cc.settings.timesHint": "You can add several times, for example 08:00, 13:00, 19:00",
